"""Generate CODEOWNERS."""

from hassfest.codeowners import validate as validate_codeowners
from hassfest.model import Config, Integration, IntegrationType

BASE = """
# This file is generated by script/hassfest/codeowners.py
# People marked here will be automatically requested for a review
# when the code that they own is touched.
# https://github.com/blog/2392-introducing-code-owners
# https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/about-code-owners

# __HA_KEEP__ Core
.core_files.yaml @universal-assistant/core
.git-blame-ignore-revs @universal-assistant/core
.gitattributes @universal-assistant/core
.gitignore @universal-assistant/core
.hadolint.yaml @universal-assistant/core
.pre-commit-config.yaml @universal-assistant/core
.prettierignore @universal-assistant/core
.yamllint @universal-assistant/core
pyproject.toml @universal-assistant/core
requirements_test.txt @universal-assistant/core
/.devcontainer/ @universal-assistant/core @edenhaus
/.github/ @universal-assistant/core
/.vscode/ @universal-assistant/core
/universalassistant/*.py @universal-assistant/core
/universalassistant/auth/ @universal-assistant/core
/universalassistant/backports/ @universal-assistant/core
/universalassistant/helpers/ @universal-assistant/core
/universalassistant/scripts/ @universal-assistant/core
/universalassistant/util/ @universal-assistant/core
/packages/hassfest/ @universal-assistant/core
/packages/pylint-universal-assistant/ @universal-assistant/core
/packages/pytest-universalassistant/ @universal-assistant/core
/script/ @universal-assistant/core

# __HA_KEEP__ Supervisor
.dockerignore @universal-assistant/supervisor
build.json @universal-assistant/supervisor
/machine/ @universal-assistant/supervisor
/rootfs/ @universal-assistant/supervisor
/Dockerfile @universal-assistant/supervisor

# Other code
/universalassistant/scripts/check_config.py @kellerza

# Agent Configurations
AGENTS.md @universal-assistant/core
/.agents/ @universal-assistant/core
/.claude/ @universal-assistant/core
/.gemini/ @universal-assistant/core

# Integrations
""".strip()

INDIVIDUAL_FILES = """
# Individual files
/universalassistant/components/demo/weather.py @fabaff
"""

REMOVE_CODEOWNERS = """
# Remove codeowners from files
/universalassistant/components/*/translations/
"""


def generate_and_validate(integrations: dict[str, Integration], config: Config) -> str:
    """Generate CODEOWNERS."""
    validate_codeowners(integrations, config)
    parts = [BASE]

    for domain in sorted(integrations):
        integration = integrations[domain]

        if integration.integration_type == IntegrationType.VIRTUAL:
            continue

        codeowners = integration.manifest["codeowners"]

        if not codeowners:
            continue

        parts.append(f"/universalassistant/components/{domain}/ {' '.join(codeowners)}")

        if (config.root / "tests/components" / domain / "__init__.py").exists():
            parts.append(f"/tests/components/{domain}/ {' '.join(codeowners)}")

    parts.append(f"\n{INDIVIDUAL_FILES.strip()}")
    parts.append(f"\n{REMOVE_CODEOWNERS.strip()}")

    return "\n".join(parts)


def validate(integrations: dict[str, Integration], config: Config) -> None:
    """Validate CODEOWNERS."""
    codeowners_path = config.root / "CODEOWNERS"
    config.cache["codeowners"] = content = generate_and_validate(integrations, config)

    if config.specific_integrations:
        return

    if codeowners_path.read_text() != content + "\n":
        config.add_error(
            "codeowners",
            "File CODEOWNERS is not up to date. Run python3 -m script.hassfest",
            fixable=True,
        )


def generate(integrations: dict[str, Integration], config: Config) -> None:
    """Generate CODEOWNERS."""
    codeowners_path = config.root / "CODEOWNERS"
    codeowners_path.write_text(f"{config.cache['codeowners']}\n")
